assert.deepEqual(clientPkg.dependencies, { '@lorcana/contracts': 'workspace:*' }); assert.equal(clientPkg.devDependencies, undefined);
const clientSrc = readFileSync('packages/match-client/src/index.ts', 'utf8');
assert.deepEqual([...clientSrc.matchAll(/from '([^']+)'/g)].map(m => m[1]).sort(), ['@lorcana/contracts', '@lorcana/contracts']);
assert.equal(/localStorage|sessionStorage|indexedDB|document\.cookie/.test(clientSrc), false, 'client persists or reads storage/cookies');
// Server-only transport code is confined to server owners; dependencies stay scoped to the match service.
const svcPkg = JSON.parse(readFileSync('apps/match-service/package.json', 'utf8'));
assert.equal(svcPkg.dependencies['@fastify/websocket'], '11.3.3'); assert.equal(svcPkg.dependencies.fastify, '5.12.5'); assert.equal(svcPkg.devDependencies.ws, '8.22.0');
