const markers = ['socket_tickets', 'transport_limits', 'lorcana_match_changed', 'pg_notify', 'createTransportStore', 'createMatchHints', 'createMatchGateway', 'createLiveConnection', 'createProjectionCache', 'submitRefs', 'match-reference-intent-v2', 'viewer-references-v2', 'synthetic-viewer-v1', 'SessionAuthority', 'private-viewer-key-v1', 'viewer-ref-v1', 'private-match-checkpoint-v1', 'restorePrivateMatch', 'createMatchRepository', 'match.command_receipts', 'lorcana_test_match', 'lorcana_local_match', 'qualification_session'];
