const routes = { ticket: (await app.inject({ method: 'POST', url: '/play/ticket', payload: {} })).statusCode, play: (await app.inject({ method: 'GET', url: '/play' })).statusCode, login: (await app.inject({ method: 'GET', url: '/login' })).statusCode };
const negotiate = await app.inject({ method: 'POST', url: '/protocol/negotiate', payload: { type: 'hello', requestId: 'audit', clientReleaseId: 'audit', supportedProtocol: { min: 1, max: 2 } } });
await app.close(); assert.deepEqual(routes, { ticket: 404, play: 404, login: 404 });
const hello = negotiate.json(); assert.equal(negotiate.statusCode, 200); assert.equal(hello.protocolVersion, 1, 'diagnostic negotiation must remain protocol1');
// Engine, adapter, Lab, vendor and existing protocol/viewer contracts are byte-identical to merged PLAY-02 main.
