assert.equal(engineDiff, '');
const kernelSha = sha(readFileSync('vendor/tcg-engines/dist/kernel.js')); assert.equal(kernelSha, 'd5e551065b0f35044b063239e057af64ffaac51f2ed1e43e0998d42f8cb71440');
// Migrations: 0001-0003 byte-identical to main, 0004 additive and recorded in both databases; new tables are match-role only.
const migrations = readdirSync('packages/db/migrations').sort();
assert.deepEqual(migrations, ['0001-foundation-probes.sql', '0002-match-commands.sql', '0003-match-receipt-invariants.sql', '0004-live-transport.sql']);
const expected = migrations.map(name => { const b = readFileSync('packages/db/migrations/' + name); if (name < '0004') assert.equal(sha(git('show', MAIN + ':packages/db/migrations/' + name)), sha(b), name + ' changed'); return [name.slice(0, 4), sha(b)]; });
const m4 = readFileSync('packages/db/migrations/0004-live-transport.sql', 'utf8');
const statements = m4.replace(/--[^\n]*/g, '').split(';').map(x => x.trim().replace(/\s+/g, ' ')).filter(Boolean).map(x => x.split(' (')[0].split(' ').slice(0, 5).join(' '));
assert.deepEqual(statements, ['ALTER TABLE match.matches DROP CONSTRAINT', 'ALTER TABLE match.matches ADD CONSTRAINT', 'CREATE TABLE match.socket_tickets', 'CREATE INDEX socket_ticket_expiry ON match.socket_tickets(expires_at)', 'CREATE TABLE match.transport_limits', 'CREATE INDEX transport_limit_expiry ON match.transport_limits(expires_at)'], '0004 must be additive: ' + JSON.stringify(statements));
const tables = ['releases', 'matches', 'command_receipts', 'journal', 'outbox', 'socket_tickets', 'transport_limits'], db = {};
for (const target of ['local', 'test']) {
  const c = client(target, 'migrator'); await c.connect();
  try {
    assert.deepEqual((await c.query('SELECT id,sha256 FROM foundation.migrations ORDER BY id')).rows.map(r => [r.id, r.sha256]), expected, target + ' history');
    for (const t of tables) {
      for (const [role, all] of [['match', true], ['api', false], ['worker', false]]) {
        const p = (await c.query("SELECT has_table_privilege($1,$2,'SELECT') s, has_table_privilege($1,$2,'INSERT') i, has_table_privilege($1,$2,'UPDATE') u, has_table_privilege($1,$2,'DELETE') d", [`lorcana_${target}_${role}`, 'match.' + t])).rows[0];
        assert.deepEqual([p.s, p.i, p.u, p.d], [all, all, all, all], target + ' ' + role + ' ' + t);
      }
      assert.equal((await c.query("SELECT count(*)::int n FROM information_schema.role_table_grants WHERE table_schema='match' AND table_name=$1 AND grantee='PUBLIC'", [t])).rows[0].n, 0);
    }
    const check = (await c.query("SELECT pg_get_constraintdef(oid) d FROM pg_constraint WHERE conname='matches_protocol_version_check'")).rows[0].d;
    assert.match(check, /1.*2/); const cols = (await c.query("SELECT column_name FROM information_schema.columns WHERE table_schema='match' AND table_name='socket_tickets' ORDER BY ordinal_position")).rows.map(r => r.column_name);
    assert.deepEqual(cols, ['ticket_hash', 'match_id', 'actor_id', 'session_id', 'session_expires_at', 'release_id', 'protocol_version', 'origin', 'expires_at']);
    db[target] = { migrations: (await c.query('SELECT count(*)::int n FROM foundation.migrations')).rows[0].n, tickets: (await c.query('SELECT count(*)::int n FROM match.socket_tickets')).rows[0].n, quotaRows: (await c.query('SELECT count(*)::int n FROM match.transport_limits')).rows[0].n, expiredQuotaRows: (await c.query('SELECT count(*)::int n FROM match.transport_limits WHERE expires_at<clock_timestamp()')).rows[0].n };
  } finally { await c.end(); }
}
